// Code Node: Process WhatsApp Status Update
// Updated for new messages table schema (from_number, to_number, updated_at)

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body;
  if (!body || !body.entry) continue;

  for (const entry of body.entry) {
    if (!entry.changes) continue;

    for (const change of entry.changes) {
      const value = change.value;
      if (!value || !value.statuses) continue;

      // Get your business phone number from metadata
      const businessPhone = value.metadata?.display_phone_number || '';
      const phoneNumberId = value.metadata?.phone_number_id || '';

      for (const statusData of value.statuses) {
        const status = statusData.status;
        const wamid = statusData.id;
        const recipientPhone = statusData.recipient_id;
        const rawTimestamp = statusData.timestamp;
        const timestampISO = new Date(parseInt(rawTimestamp) * 1000).toISOString();

        const updatePayload = {
          wamid: wamid,
          status: status,
          from_number: businessPhone,   // Status updates are for outbound messages (from you)
          to_number: recipientPhone,    // To the customer
          direction: 'outbound',
          updated_at: new Date().toISOString(),
        };

        // Assign timestamp field based on status
        if (status === 'sent') {
          updatePayload.sent_at = timestampISO;
        } else if (status === 'delivered') {
          updatePayload.delivered_at = timestampISO;
        } else if (status === 'read') {
          updatePayload.read_at = timestampISO;
        } else if (status === 'failed') {
          updatePayload.failed_at = timestampISO;
          // Capture failure reason if available
          if (statusData.errors && statusData.errors.length > 0) {
            updatePayload.failure_reason = statusData.errors
              .map(e => `${e.code}: ${e.title} - ${e.message || ''}`)
              .join('; ');
          }
        }

        // Pricing info
        if (statusData.pricing) {
          updatePayload.is_billable = statusData.pricing.billable;
          updatePayload.pricing_model = statusData.pricing.pricing_model;
          updatePayload.pricing_category = statusData.pricing.category;
        }

        // Include metadata for reference
        updatePayload.phone_number_id = phoneNumberId;

        results.push({ json: updatePayload });
      }
    }
  }
}

return results;

