// Code Node: Process Inbound WhatsApp Message
// Place this AFTER the Switch node "Incoming Message" output
// BEFORE the If3 node
// This prepares data for contacts upsert, inbound message logging, and lead creation

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body;
  if (!body || !body.entry) continue;

  for (const entry of body.entry) {
    if (!entry.changes) continue;

    for (const change of entry.changes) {
      const value = change.value;
      if (!value || !value.messages) continue;

      const metadata = value.metadata || {};
      const businessPhone = metadata.display_phone_number || '';
      const phoneNumberId = metadata.phone_number_id || '';

      for (const msg of value.messages) {
        const contact = value.contacts?.[0] || {};
        const customerPhone = msg.from;
        const customerName = contact.profile?.name || '';
        const waId = contact.wa_id || customerPhone;
        const msgTimestamp = new Date(parseInt(msg.timestamp) * 1000).toISOString();

        // Determine message content based on type
        let messageBody = '';
        let messageType = msg.type || 'text';
        let buttonText = '';
        let isReply = false;
        let replyToWamid = '';
        let mediaUrl = '';
        let mediaMimeType = '';

        switch (messageType) {
          case 'text':
            messageBody = msg.text?.body || '';
            break;
          case 'button':
            buttonText = msg.button?.text || '';
            messageBody = buttonText;
            break;
          case 'image':
            messageBody = msg.image?.caption || '[Image]';
            mediaUrl = msg.image?.id || '';
            mediaMimeType = msg.image?.mime_type || '';
            break;
          case 'video':
            messageBody = msg.video?.caption || '[Video]';
            mediaUrl = msg.video?.id || '';
            mediaMimeType = msg.video?.mime_type || '';
            break;
          case 'audio':
            messageBody = '[Audio]';
            mediaUrl = msg.audio?.id || '';
            mediaMimeType = msg.audio?.mime_type || '';
            break;
          case 'document':
            messageBody = msg.document?.caption || msg.document?.filename || '[Document]';
            mediaUrl = msg.document?.id || '';
            mediaMimeType = msg.document?.mime_type || '';
            break;
          case 'location':
            messageBody = `[Location: ${msg.location?.latitude}, ${msg.location?.longitude}]`;
            break;
          case 'reaction':
            messageBody = msg.reaction?.emoji || '[Reaction]';
            break;
          case 'interactive':
            messageBody = msg.interactive?.button_reply?.title || 
                         msg.interactive?.list_reply?.title || 
                         '[Interactive]';
            break;
          default:
            messageBody = `[${messageType}]`;
        }

        // Check if this is a reply to a previous message
        if (msg.context) {
          isReply = true;
          replyToWamid = msg.context.id || '';
        }

        const output = {
          // Contact data (for contacts table upsert)
          contact_phone: waId,
          contact_name: customerName,

          // Inbound message data (for messages table insert)
          inbound_wamid: msg.id,
          from_number: customerPhone,
          to_number: businessPhone,
          direction: 'inbound',
          message_type: messageType,
          message_body: messageBody,
          button_text: buttonText,
          is_reply: isReply,
          reply_to_wamid: replyToWamid,
          media_url: mediaUrl,
          media_mime_type: mediaMimeType,
          status: 'delivered',
          delivered_at: msgTimestamp,
          sent_at: msgTimestamp,

          // Metadata
          business_phone: businessPhone,
          phone_number_id: phoneNumberId,
          msg_timestamp: msgTimestamp,

          // Pass through original data for downstream nodes
          original_body: body,
        };

        results.push({ json: output });
      }
    }
  }
}

return results;

